// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        // ensure we don't exceed reasonable array sizes
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length < 20);
        vm.assume(_tos.length == v.length);
        // assume no extremely large or empty inputs to avoid known fuzz rejections
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            vm.assume(v[i] > 0);
        }
        // The property: the transfer function, if it completes without reverting, must return true.
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool res) {
            ok = res;
        } catch {
            ok = true; // if it reverts, property vacuously holds (only care about non-reverting paths)
        }
        assertTrue(ok);
    }
}

