import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(this));
        vm.assume(caddress != address(c));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
            assertTrue(false); // This catch should not execute if the call doesn't revert; we assert here to make the test fail for unexpected reverts, but the main assertion is below. Actually, we only want to assert if the call succeeds. We'll restructure.
        }
        // The call succeeded; return value must be true
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool externalCallSuccess = true;
        for (uint i = 0; i < _tos.length; i++) {
            (bool ok, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], v[i]));
            if (!ok) {
                externalCallSuccess = false;
                break;
            }
        }

        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            ret = r;
        } catch {
            vm.assume(false);
        }

        assertTrue(ret == externalCallSuccess);
    }
}
